// Minimal libFuzzer-style driver for fuzz_config: reads a file and calls
// LLVMFuzzerTestOneInput once (like `fuzz_config <file>` with -runs=1).
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <vector>

extern "C" int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size);

int main(int argc, char **argv) {
  if(argc != 2) {
    fprintf(stderr, "usage: %s <input-file>\n", argv[0]);
    return 2;
  }
  FILE *f = fopen(argv[1], "rb");
  if(!f) { perror("fopen"); return 2; }
  fseek(f, 0, SEEK_END);
  long n = ftell(f);
  fseek(f, 0, SEEK_SET);
  if(n < 0) { fclose(f); return 2; }
  std::vector<uint8_t> buf((size_t)n);
  if(n > 0 && fread(buf.data(), 1, (size_t)n, f) != (size_t)n) { fclose(f); return 2; }
  fclose(f);
  LLVMFuzzerTestOneInput(buf.data(), buf.size());
  return 0;
}

